import {sceneName,stats,labels,normalizeBundle,readFiles,plain} from './modules/data.js';
import * as storage from './modules/storage.js';
import {icon,esc,button,el,toast,openSheet,closeSheet} from './modules/ui.js';
let data,small,progress={},cleanup=()=>{},saveFailed=false;
const defaults={role:'',scene:'all',font:20,leading:1.9,stick:true,read:{},sessions:{},range:{scene:'all',from:1,to:0},rate:1};
const app=document.querySelector('#app');
const roles=()=>[...new Set(data.lines.map(l=>l.speaker))];
const key=()=>`mt-state:${data.id}`;
function loadState(){small={...structuredClone(defaults),...storage.loadSmall(key(),{})};progress=storage.loadSmall(`mt-progress:${data.id}`,{});if(!roles().includes(small.role))small.role=roles()[0];}
function save(){try{storage.saveSmall(key(),small);storage.saveSmall(`mt-progress:${data.id}`,progress);if(saveFailed){saveFailed=false;document.querySelector('.save-error')?.remove();}}catch{saveFailed=true;if(!document.querySelector('.save-error')){const b=el(`<div class="save-error" role="alert">端末に保存できません。バックアップを保存してください。${button('バックアップ','export','secondary')}</div>`);b.querySelector('button').onclick=exportBackup;document.body.append(b);}}}
function setProgress(id,value){const old=progress[id]?{...progress[id]}:undefined;progress[id]=value;save();toast(value.review?'要復習に追加しました':`学習状態: ${labels[value.level||0]}`,()=>{if(old)progress[id]=old;else delete progress[id];save();window.dispatchEvent(new CustomEvent('progresschange',{detail:id}));});window.dispatchEvent(new CustomEvent('progresschange',{detail:id}));}
function navItem(route,text,ico){return `<a class="nav-item" href="#${route}" ${route===(location.hash.slice(1)||'home')?'aria-current="page"':''}>${icon(ico)}<span>${text}</span></a>`;}
function shell(){app.innerHTML=`<div class="app-layout"><aside class="sidebar"><a href="#home" class="brand"><img src="./icon.svg" alt=""><span>Mousetrap<br>Trainer</span></a><nav class="nav-items" aria-label="メイン">${navItem('home','ホーム','home')}${navItem('script','台本','book')}${navItem('rehearse','稽古','play')}</nav><div class="sidebar-bottom">${navItem('settings','設定','settings')}<div class="local-status"><span class="dot"></span><span>この端末に保存<br><small>アカウント登録なし</small></span></div></div></aside><div class="main-shell"><header class="topbar"><a class="brand mobile-brand" href="#home"><img src="./icon.svg" alt=""><span>Mousetrap Trainer</span></a><div class="desktop-only"><div class="eyebrow">YOUR REHEARSAL COMPANION</div></div><div class="toolbar-actions">${data.sample?'<span class="pill sample-pill">練習用サンプル</span>':'<span class="pill desktop-only">端末内の台本</span>'}<button class="icon-button" data-action="settings-sheet" aria-label="設定を開く">${icon('settings')}</button></div></header><main id="main" class="main-content" style="display:contents"></main></div><nav class="bottom-nav" aria-label="メイン">${navItem('home','ホーム','home')}${navItem('script','台本','book')}${navItem('rehearse','稽古','play')}${navItem('settings','設定','settings')}</nav></div>`;}
async function render(){cleanup();cleanup=()=>{};if(document.querySelector('#sheet').open)closeSheet();shell();const main=app.querySelector('#main'),route=location.hash.slice(1)||'home';
 if(route==='script'){const {mountReader}=await import('./modules/reader.js');cleanup=mountReader(main,context());}
 else if(route==='rehearse'){const {mountRehearsal}=await import('./modules/rehearsal.js');cleanup=mountRehearsal(main,context());}
 else if(route==='settings')renderSettings(main);else renderHome(main);
 app.querySelector('[data-action=settings-sheet]')?.addEventListener('click',()=>{location.hash='settings';});
}
function context(){return {data,small,progress,save,setProgress,roles,go:(route)=>{location.hash=route;},openImport,settings:()=>{location.hash='settings';}};}
function roleHTML(){return `<select id="home-role" class="role-select" aria-label="自分の役">${roles().map(r=>`<option ${r===small.role?'selected':''}>${esc(r)}</option>`).join('')}</select>`;}
function renderHome(main){const st=stats(data,progress,small.role),last=data.lines.find(l=>l.id===small.read.id),active=last?.scene||(small.scene==='all'?data.scenes[0].id:small.scene);
 main.innerHTML=`<div class="page-scroll"><div class="page"><div class="page-intro"><div class="eyebrow">READ. UNDERSTAND. REHEARSE.</div><h1>一行ずつ、自分の言葉に。</h1><p class="subtle">読む、理解する、声にする。今日も台本をひらこう。</p></div><section class="continue-panel"><div><div class="eyebrow">${last?'CONTINUE READING':'YOUR SCRIPT'}</div><h2>${esc(data.title)}</h2><p class="subtle">${esc(sceneName(active))}${last?` · 発話 ${last.ordinal} から`:' · 最初の一行から'}</p><div class="button-row">${button(last?'続きから読む':'台本を読む','read','primary','book')}${button('稽古を始める','practice','secondary','play')}</div></div><div class="book-mark" aria-hidden="true">${icon('book')}</div></section><div class="home-grid"><section><div class="role-box"><div class="role-monogram">${esc(small.role[0])}</div><div style="min-width:0;flex:1"><label for="home-role">自分の役</label>${roleHTML()}</div></div><div class="section-heading"><h2>セリフの定着</h2><span class="subtle">${st.total} 発話</span></div><div class="progress-big"><strong>${st.percent}<span>%</span></strong><span>暗記済み ${st.counts[2]} / ${st.total}</span></div><div class="progress-track" aria-label="暗記済み ${st.percent}%"><span style="background:var(--green);width:${st.percent}%"></span><span style="background:#e5b35c;width:${st.total?st.counts[1]/st.total*100:0}%"></span></div><div class="progress-legend">${st.counts.map((n,i)=>`<span><i style="background:${['#ccc8ba','#e5b35c','var(--green)'][i]}"></i>${labels[i]} ${n}</span>`).join('')}</div>${st.review?`<div style="margin-top:20px">${button(`要復習のセリフ ${st.review}件`,'review','text-button','bookmark')}</div>`:''}</section><section><div class="section-heading"><h2>幕・場面から読む</h2><span class="eyebrow">SCENES</span></div><div class="scene-list">${data.scenes.map((s,i)=>`<button class="scene-link" data-scene="${esc(s.id)}"><span class="scene-number">${i+1}</span><span class="scene-link-text"><strong>${esc(s.title)}</strong><small>${s.lines.length} 発話 · 自分のセリフ ${s.lines.filter(id=>data.lines.find(l=>l.id===id)?.speaker===small.role).length}</small></span>${icon('chevron')}</button>`).join('')}</div></section></div>${Object.keys(small.sessions).length?`<div class="import-banner"><div><h3>途中の稽古があります</h3><p class="subtle">前回止めた発話から、いつでも再開できます。</p></div>${button('稽古の続きを開く','practice','secondary','play')}</div>`:''}<section class="import-banner"><div><h3>${data.sample?'自分の台本で、はじめよう':'台本データを管理'}</h3><p class="subtle">${data.sample?'バックアップZIP、または台本・翻訳などのJSONを選択。':'データの更新後も、同じ発話IDの学習記録を引き継ぎます。'}<br>選んだデータは、この端末の外へ送信されません。</p></div>${button('台本を読み込む','import','secondary','upload')}</section></div></div>`;
 main.querySelector('[data-action=read]').onclick=()=>{if(!last)small.scene=active;save();location.hash='script';};main.querySelector('[data-action=practice]').onclick=()=>{location.hash='rehearse';};main.querySelector('[data-action=import]').onclick=openImport;
 main.querySelector('#home-role').onchange=e=>{small.role=e.target.value;save();render();};main.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{small.scene=b.dataset.scene;small.read={};save();location.hash='script';});
 main.querySelector('[data-action=review]')?.addEventListener('click',()=>{small.scene='all';small.speaker=small.role;small.reviewOnly=true;save();location.hash='script';});
}
function renderSettings(main){main.innerHTML=`<div class="page-scroll"><div class="page" style="max-width:900px"><div class="page-intro"><div class="eyebrow">MAKE IT YOURS</div><h1>設定</h1><p class="subtle">読みやすさも、稽古のペースも、自分に合わせて。</p></div><section class="setting-group"><h2>読む</h2><div class="setting-row"><label for="font-size">英文の文字サイズ<p><output id="font-output">${small.font}</output> px</p></label><input id="font-size" type="range" min="16" max="32" step="1" value="${small.font}"></div><div class="setting-row"><label for="line-height">行間</label><select id="line-height"><option value="1.6">コンパクト</option><option value="1.9">標準</option><option value="2.2">ゆったり</option></select></div><div class="setting-row"><label for="show-stick">スクロールスティック<p>上下に倒して移動。同方向に素早く2回で自分のセリフへ。</p></label><input id="show-stick" type="checkbox" ${small.stick?'checked':''}></div></section><section class="setting-group"><h2>音声</h2><div class="setting-row"><div><strong>録音ファイル</strong><p>発話ID.mp3 など。音声は端末内に保存します。</p></div>${button('音声を追加','audio-import','secondary','audio')}</div><div class="setting-row"><label for="playback-rate">再生速度</label><select id="playback-rate">${[.75,1,1.25,1.5].map(n=>`<option value="${n}">${n}倍</option>`).join('')}</select></div></section><section class="setting-group"><h2>台本と学習記録</h2><div class="setting-row"><div><strong>${esc(data.title)}</strong><p>${data.lines.length} 発話 · ${data.scenes.length} 場面 · ${Object.keys(data.dictionary).length} 辞書項目</p></div>${button('読み込む','import','secondary','upload')}</div><div class="setting-row"><div><strong>バックアップを保存</strong><p>台本・進捗・閲覧位置・稽古の続きをJSONで保存。音声は含みません。</p></div>${button('保存','export','secondary','download')}</div><div class="setting-row"><div><strong>バックアップから復元</strong><p>同じ発話の進捗は、新しい更新日時の記録を優先します。</p></div>${button('選択','restore','secondary','refresh')}</div><div class="setting-row"><div><strong>サンプルに切り替え</strong><p>読み込んだ台本と学習記録は保持されます。</p></div>${button(data.sample?'サンプルを使用中':'サンプルを開く','sample','secondary')}</div>${!data.sample?`<div class="setting-row"><div><strong>読み込み済みの台本</strong><p>サンプルから、保存した台本へ戻れます。</p></div>${button('台本一覧','library','secondary')}</div>`:`<div class="setting-row"><div><strong>保存した台本に戻る</strong></div>${button('台本一覧','library','secondary')}</div>`}</section><section class="setting-group"><h2>アプリ</h2><div class="setting-row"><div><strong>ホーム画面に追加</strong><p id="install-note">インストールすると、アプリとしてすぐに開けます。</p></div>${button('インストール','install','secondary','download')}</div><div class="setting-row"><div><strong>オフライン</strong><p id="offline-note">状態を確認しています…</p></div>${button('更新を確認','update','secondary','refresh')}</div></section><div class="notice">学習データはこのブラウザーに保存されます。端末の変更やブラウザーのデータ削除に備えて、バックアップを保存してください。</div><p class="version">Mousetrap Trainer 1.0 · アカウント不要 / 外部送信なし</p></div></div>`;
 main.querySelector('#line-height').value=small.leading;main.querySelector('#playback-rate').value=small.rate;
 main.querySelector('#font-size').oninput=e=>{small.font=+e.target.value;main.querySelector('#font-output').textContent=small.font;save();};main.querySelector('#line-height').onchange=e=>{small.leading=+e.target.value;save();};main.querySelector('#show-stick').onchange=e=>{small.stick=e.target.checked;save();};main.querySelector('#playback-rate').onchange=e=>{small.rate=+e.target.value;save();};
 const actions={import:openImport,restore:openImport,export:exportBackup,sample:async()=>{await activate(normalizeBundle(await (await fetch('./sample.json')).json()));render();},library:showLibrary,'audio-import':async()=>{const {openAudioImport}=await import('./modules/audio.js');openAudioImport(context());},install:installApp,update:checkUpdate};
 for(const [a,fn] of Object.entries(actions))main.querySelector(`[data-action=${a}]`)?.addEventListener('click',fn);
 refreshOffline();
}
async function activate(next){await storage.atomicPut([[`script:${next.id}`,next],['active-script',next.id]]);data=next;loadState();save();}
async function showLibrary(){const ids=await storage.get('script-list')||[];const items=[];for(const id of ids){const d=await storage.get(`script:${id}`);if(d)items.push(d);}openSheet('保存した台本',items.length?items.map(d=>`<button class="scene-link" data-work="${esc(d.id)}"><span class="scene-link-text"><strong>${esc(d.title)}</strong><small>${d.lines.length}発話</small></span>${icon('chevron')}</button>`).join(''):'<p>まだ読み込んだ台本はありません。</p>',{setup:d=>{d.querySelectorAll('[data-work]').forEach(b=>b.onclick=async()=>{const next=await storage.get(`script:${b.dataset.work}`);await activate(next);closeSheet();render();});}});}
function openImport(){openSheet('台本データを読み込む',`<p>バックアップZIPを1つ、または台本・翻訳・語彙・文法・辞書のJSONをまとめて選んでください。</p><p class="subtle" style="margin-top:12px">JSON / ZIP · 1ファイル50MB以内。データは端末内で処理・保存します。</p><div style="margin-top:24px">${button('ファイルを選ぶ','choose-files','primary','upload')}</div><div id="import-result" class="sheet-section"><h3>対応ファイル</h3><p class="subtle">mousetrap_script_data.json ほか<br>The_Mousetrap_Production_Data_DEPLOY_READY.zip<br>このアプリから保存したバックアップJSON</p></div>`,{setup:d=>{d.querySelector('[data-action=choose-files]').onclick=()=>document.querySelector('#data-files').click();}});}
document.querySelector('#data-files').onchange=async e=>{
 const files=[...e.target.files];e.target.value='';if(!files.length)return;const result=document.querySelector('#import-result');if(!result)return;result.innerHTML='<p role="status">データの対応を確認しています…</p>';
 try{const read=await readFiles(files);let next=read.data,backup=read.backup;
  if(backup){if(!backup.data?.lines)throw Error('バックアップの台本がありません。');next=validateSaved(backup.data);}
  result.innerHTML=`<h3>読み込み内容</h3><p><strong>${esc(next.title)}</strong></p><div class="data-summary"><div><strong>${next.lines.length}</strong><span>発話</span></div><div><strong>${next.scenes.length}</strong><span>場面</span></div><div><strong>${Object.keys(next.dictionary).length}</strong><span>辞書項目</span></div></div>${next.warnings.length?`<p class="notice">${esc(next.warnings.join(' / '))}<br>未収録の項目は「未収録」と表示します。</p>`:''}<p class="subtle">${backup?'バックアップの設定・閲覧位置・稽古の続きを復元します。':'同じIDの台本を更新しても、学習記録は引き継ぎます。'}</p><div style="margin-top:20px">${button(backup?'復元して開く':'この台本を使う','confirm-import','primary')}</div>`;
  result.querySelector('button').onclick=async()=>{try{
   if(backup){const existing=storage.loadSmall(`mt-progress:${next.id}`,{});for(const [id,p] of Object.entries(backup.progress||{})){if(!existing[id]||(p.updatedAt||0)>(existing[id].updatedAt||0))existing[id]=p;}storage.saveSmall(`mt-progress:${next.id}`,existing);storage.saveSmall(`mt-state:${next.id}`,{...defaults,...backup.settings});}
   await activate(next);const list=await storage.get('script-list')||[];if(!list.includes(next.id)){list.push(next.id);await storage.put('script-list',list);}await navigator.storage?.persist?.();closeSheet();location.hash='home';await render();toast(`${next.lines.length}発話を読み込みました`);
  }catch(err){result.innerHTML=`<p class="notice error" role="alert">保存できませんでした。${esc(err.message)}</p>`;}};
 }catch(err){result.innerHTML=`<p class="notice error" role="alert">読み込めませんでした。${esc(err.message)}</p>`;}
};
function validateSaved(saved){const script={};for(const scene of saved.scenes||[])script[scene.id]={speeches:saved.lines.filter(l=>l.scene===scene.id)};return normalizeBundle({...saved,script});}
async function exportBackup(){const output={format:'mousetrap-backup-v1',exportedAt:new Date().toISOString(),data,settings:small,progress};downloadJSON(output,'mousetrap-backup.json');toast('バックアップを保存しました');}
function downloadJSON(v,name){const url=URL.createObjectURL(new Blob([JSON.stringify(v,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
let installPrompt,registration;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});window.addEventListener('appinstalled',()=>{installPrompt=null;toast('インストールしました');});
async function installApp(){if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;}else openSheet('ホーム画面に追加',`<p>Android / Chrome：ブラウザーのメニューから「アプリをインストール」または「ホーム画面に追加」を選びます。</p><div class="sheet-section"><p>iPhone / iPad：Safariの共有メニューから「ホーム画面に追加」を選びます。</p></div><div class="sheet-section"><p class="subtle">すでにインストール済みの場合は、そのまま使えます。ブラウザーによってインストール操作は異なります。</p></div>`);}
async function refreshOffline(){const target=document.querySelector('#offline-note');if(!target)return;const cached=await caches.has('mousetrap-shell-v1');target.textContent=cached?'アプリを端末に保存済み。読み込んだ台本はオフラインでも使えます。':'初回の保存を準備中です。通信した状態で一度開いてください。';}
async function checkUpdate(){if(!registration){toast('更新機能を準備中です。ページを再読み込みしてください。');return;}try{await registration.update();if(registration.waiting)openSheet('更新を適用',`<p>閲覧位置と学習記録を保存して更新します。</p>${button('保存して更新','apply-update','primary')}`,{setup:d=>d.querySelector('button[data-action]').onclick=()=>{save();registration.waiting.postMessage('activate');}});else toast('更新を確認しました。新しい更新はありません。');}catch{toast('更新を確認できません。通信状態を確認してください。');}}
window.addEventListener('hashchange',render);window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden)save();});
window.addEventListener('storage',e=>{if(e.key===`mt-progress:${data?.id}`){progress=storage.loadSmall(e.key,{});render();}});
window.addEventListener('offline',()=>toast('オフラインです。端末に保存した台本を使えます。'));
try{const active=await storage.get('active-script');data=active?await storage.get(`script:${active}`):null;if(!data){data=normalizeBundle(await(await fetch('./sample.json')).json());await activate(data);}else loadState();await render();
 if('serviceWorker'in navigator){registration=await navigator.serviceWorker.register('./sw.js');registration.addEventListener('updatefound',()=>{const worker=registration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)toast('アプリの更新があります。設定から適用できます。');if(worker.state==='activated')refreshOffline();});});let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!refreshing){refreshing=true;save();location.reload();}});}
}catch(err){app.innerHTML=`<div class="page"><h1>アプリを開けませんでした</h1><p class="notice error" style="margin:24px 0">${esc(err.message)}</p><p>ブラウザーのストレージが利用できるか確認してください。プライベートブラウズでは保存が制限されることがあります。</p><button class="primary" onclick="location.reload()">再試行</button></div>`;}
